import pathlib,json,hashlib,subprocess,time,tarfile,sys
npm=pathlib.Path('/home/qian-qi/work/hepta-rea-reference-20261103/install/node_modules/rea-agents')
tar=pathlib.Path('/home/qian-qi/work/hepta-rea-reference-20261103/pack/rea-agents-6.8.0.tgz')
assert hashlib.sha256(tar.read_bytes()).hexdigest()=='8d542ec76a9cb350584b60a6c9c088706ff812d5bb5b094c20c95b6dc25698bb'
checked=0
with tarfile.open(tar) as archive:
 for member in archive:
  if member.isfile():
   name=member.name.removeprefix('package/')
   assert (npm/name).read_bytes()==archive.extractfile(member).read(),name
   checked+=1
out=pathlib.Path('/home/qian-qi/work/hepta-rea-contracts-20261104-r4-evidence/apk/evidence-file-alias-reference-r1')
out.mkdir()
work=out/'workspace';work.mkdir()
fixture=pathlib.Path('/home/qian-qi/work/hepta-rea-contracts-20261104-r4/apk/tests/fixtures/rea_evidence_file/bare-record.json')
(work/'bare.json').write_bytes(fixture.read_bytes())
(work/'empty.json').write_bytes(b'')
(work/'directory').mkdir()
alias=str(work)+'//./'
cases=[
 dict(name='missing-alias',path=alias+'absent.json',api='read'),
 dict(name='empty-alias',path=alias+'empty.json',api='read',hex=''),
 dict(name='bare-source-alias',path=alias+'bare.json',api='read-with-source'),
 dict(name='bare-selector-alias',path=alias+'bare.json',api='select',evidence_id='ev_'+'0'*64),
 dict(name='file-trailing-slash',path=alias+'bare.json//',api='read'),
 dict(name='file-trailing-dot',path=alias+'bare.json/.',api='read'),
 dict(name='directory-alias',path=alias+'directory//.',api='read'),
]
request=dict(npm=str(npm),cases=cases)
(out/'request.json').write_text(json.dumps(request,indent=2)+'\n')
runner=r"""
import fs from 'node:fs/promises';
import {pathToFileURL} from 'node:url';
const out=process.argv[2];
const request=JSON.parse(await fs.readFile(out+'/request.json','utf8'));
const {readJsonFile,readJsonFileWithSource}=await import(pathToFileURL(request.npm+'/dist/application/JsonFiles.js'));
const {readEvidenceFileSource}=await import(pathToFileURL(request.npm+'/dist/application/analysisView/evidenceFileSource.js'));
const {absoluteCallerPath}=await import(pathToFileURL(request.npm+'/dist/filesystem/callerPath.js'));
const {projectAnalysisError}=await import(pathToFileURL(request.npm+'/dist/domain/analysisErrorProjection.js'));
const cases=[];
for(const row of request.cases){
 const result=row.api==='select'?await readEvidenceFileSource(row.path,{},row.evidence_id):row.api==='read-with-source'?await readJsonFileWithSource(row.path,undefined,undefined,'inspect_analysis_view'):await readJsonFile(row.path,undefined,undefined,'inspect_analysis_view');
 const expected=result.ok?{ok:true,selected_path:result.value.path,evidence_id:result.value.data?.evidence_id}:{ok:false,typed_error:Object.fromEntries(Object.entries(result.error).filter(([k])=>k!=='cause')),projected:projectAnalysisError(result.error)};
 cases.push({...row,normalized_path:absoluteCallerPath(row.path),expected});
}
await fs.writeFile(out+'/goldens.json',JSON.stringify({format:'hepta.evidence-file-alias-original.v1',node:process.version,cases},null,2)+'\n');
console.log(JSON.stringify(cases));
"""
(out/'runner.mjs').write_text(runner)
start=time.monotonic()
with (out/'stdout.log').open('wb') as stdout,(out/'stderr.log').open('wb') as stderr:
 process=subprocess.run(['node',str(out/'runner.mjs'),str(out)],cwd=out,stdout=stdout,stderr=stderr,timeout=90)
assert process.returncode==0,process.returncode
data=(out/'goldens.json').read_bytes();goldens=json.loads(data)
assert len(goldens['cases'])==7
for c in goldens['cases']:
 if c['name']=='bare-source-alias':assert c['expected']['selected_path']==c['normalized_path']
 elif c['name']=='bare-selector-alias':assert c['path'] in c['expected']['projected']['message']
 else:assert c['expected']['projected']['details']['path']==c['normalized_path']
summary=dict(passed=True,exit_code=0,seconds=time.monotonic()-start,budget_seconds=90,cases=7,checked_npm_files=checked,goldens_sha256=hashlib.sha256(data).hexdigest(),goldens_bytes=len(data),frozen_npm_tarball_sha256=hashlib.sha256(tar.read_bytes()).hexdigest(),source_sha256={p:hashlib.sha256((npm/p).read_bytes()).hexdigest() for p in ['dist/filesystem/callerPath.js','dist/application/JsonFiles.js','dist/application/analysisView/evidenceFileSource.js']})
(out/'qualification.json').write_text(json.dumps(summary,indent=2)+'\n')
print(json.dumps(summary),flush=True)
print(data.decode(),flush=True)
